import { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { useFormik } from "formik";
import * as Yup from "yup";
import { Helmet } from "react-helmet";

export default function Forgetpass() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  let navigate = useNavigate();

  async function forget(values) {
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      let { data } = await axios.post(
        "https://mcishop.vercel.app/api/v1/auth/forgetPassword",
        values,
        {
          headers: { "Content-Type": "application/json" },
        }
      );

      if (data.message === "check your email") {
        setSuccess("A reset link has been sent to your email.");
        setLoading(false);
      }
    } catch (err) {
      setError(err.response?.data?.message || "Something went wrong.");
      setLoading(false);
    }
  }

  let validationSchema = Yup.object({
    email: Yup.string().email("Invalid email!").required("Email is required!"),
  });

  let formik = useFormik({
    initialValues: { email: "" },
    validationSchema,
    onSubmit: forget,
  });

  return (
    <>
      <Helmet>
        <title>Change Password</title>
      </Helmet>
      <div className="w-50 mx-auto py-4 my-5" >
        {error && <div className="alert alert-danger py-2 mt-4">{error}</div>}
        {success && <div className="alert alert-success py-2 my-3">{success}</div>}

        <form onSubmit={formik.handleSubmit}>
          <input
            placeholder="Enter your Email"
            type="email"
            id="email"
            value={formik.values.email}
            className="mb-2 form-control"
            onChange={formik.handleChange}
            onBlur={formik.handleBlur}
          />
          {formik.errors.email && formik.touched.email && (
            <div className="alert alert-danger py-2">{formik.errors.email}</div>
          )}

          {loading ? (
            <button type="button" className="btn bg-main text-white">
              <i className="fas fa-spinner fa-spin"></i>
            </button>
          ) : (
            <button
              disabled={!(formik.isValid && formik.dirty)}
              type="submit"
              className="btn bg-main text-white"
            >
              Next
            </button>
          )}
        </form>
      </div>
    </>
  );
}

