import './App.css';
import  { Toaster } from 'react-hot-toast';
import Layout from './component/Layout/Layout.jsx';
import Navbar from './component/Navbar/Navbar.jsx';
import {createBrowserRouter, createHashRouter, RouterProvider  } from "react-router-dom"
import UserTokenProvider from './Context/UserToken.js';
import Products from './component/Products/Products.jsx';
import About from './component/About/About.jsx';
import Home from './component/Home/Home.jsx';
import Signup from './component/Signup/Signup.jsx';
import Signin from './component/Signin/Signin.jsx';
import Brands from './component/Brands/Brands.jsx';
import BrandDetails from './component/BrandDetails/BrandDetails.jsx';
import ProductDetails from './component/ProductDetails/ProductDetails.jsx';
import Notfound from './component/Notfound/Notfound.jsx';
import ProtectedRoute from './component/ProtectedRoute/ProtectedRoute.jsx';
import Cart from './component/Cart/Cart.jsx';
import CartContextProvider from './Context/CartContext.js';
import Filter from './component/Filteration/Filter.jsx';
import Srevices from './component/Services/Srevices.jsx';
import AccountDetials from './component/AccountDetails/AccountDetials.jsx';
import Categories from './component/Categories/Categories.jsx';
import Subcategorydetails from './component/SubcategoryDetails/Subcategorydetails.jsx';
import Categorydetails from './component/CategoryDetails/Categorydetails.jsx';
import CheckoutDetails from './component/CheckoutDetails/CheckoutDetails.jsx';
import Forgetpass from './component/ForgetPass/Forgetpass.jsx';
import Resetpassword from './component/ResetPassword/Resetpassword.jsx';
import Personal from './component/Personal/Personal.jsx';
import Orders from './component/Orders/Orders.jsx';


function App() {
  let routers =  createHashRouter([
    {path:'/' , element:<Layout/> , children:[
      {index:true , element:<Home/>},
      {path:'/brands' , element:<Brands/> },
      {path:'/products' , element:<Products/> },
      {path:'/categories' , element:<Categories/> },
      {path:'/checkout' , element:<CheckoutDetails/> },
      {path:'/productDetails/:slug' , element: <ProductDetails/> },
      {path:'/brandDetails/:slug' , element:<BrandDetails/> },
      {path:'/categories/:categorySlug' , element:<Categorydetails/> },
      {path:'/categories/:categorySlug/subcategories/:subcategorySlug' , element:<Subcategorydetails/> },
      {path:'/about' , element:<About/> },
      {path:'/login', element:<Signin/>},
      {path:'/personal/:user_id', element:<Personal/>},
      {path:'/forgetPass', element:<Forgetpass/>},
      {path:'/resetPass/:token', element:<Resetpassword/>},
      {path:'/register', element:<Signup/>},
      {path:'/cart' , element:<Cart/>},
      {path:'/orders/:user_id' , element:<Orders/>},
     {path:"/filter" , element:<Filter/>},
     {path:"/services" , element:<Srevices/>},
     {path:"/account" , element:<AccountDetials/>},
    
      {path:'*', element:<Notfound/>},
      
    ]}
  ])

  return<>
 <CartContextProvider>
 <UserTokenProvider>
     <RouterProvider router={routers}></RouterProvider>
     <Toaster/>
     </UserTokenProvider>
 </CartContextProvider>
  </>
}

export default App;
