import axios from 'axios';
import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom';

export default function CategSideBar() {
  const [wid, setWid] = useState(0);
   const [hoveredCat, setHoveredCat] = useState(null);
    const [catg , setCatg ]=useState(null)
    let [settings , setSettings]=useState()
   async function getSettings() {
     let {data} = await axios.get(`http://localhost:3000/api/v1/settings/`)
       setSettings(data?.setts[0])
    // console.log(data?.setts[0]);
    } 
  useEffect(() => {
    getSettings()
  }, [])
      async function getCateg() {
           const {data} = await axios.get(`https://mcishop.vercel.app/api/v1/categories`)
         //  console.log(data);
           if(data?.categories){
           setCatg(data)
          // console.log(catg);
           }
      }
      //  function test(){
      //    setWid(0)
      //  }
      
      
     useEffect(()=>{
          getCateg()
     }, [])
  return  <>
      <div>
                 
           <div className='catgbar h-100 py-4 bg-body-tertiary' > 
       
       <div className="row mx-auto">
       <div className=' pt-1  col-md-1 bars'>
 <i className="fa-solid fa-bars h5 " style= {{color:"#ef4423"}}></i>
          </div>
          <div className="text-light test1  col-md-6 cursor-pointer ">
             <h4 style= {{color:"#ef4423"}}>Menu</h4>
          </div>
       </div>
          <div className="row mb-4 test2 mx-auto">
            {catg?.categories.map((cat)=>(
                         
                <div key={cat._id}
                 onMouseEnter={() => setHoveredCat(cat)}
                onMouseLeave={() => setHoveredCat(null)}
                className='categ  my-3 h6 text-secondary fa-bold cursor-pointer position-relative'>
                   <Link className='text-secondary' to={`categories/${cat.slug}`}> <li className=' list-unstyled'>{cat.name}</li></Link>
                     {hoveredCat === cat && (
         <div className="subcategories">
           {cat.subcategories?.length > 0 ? (
             cat.subcategories.map((sub) => (
               <div key={sub._id} className="subcategory-item">
               <Link className='text-secondary' to={`categories/${cat.slug}/subcategories/${sub.slug}`}> <li className=' list-unstyled'>{sub.name}</li></Link>
               </div>
             ))
           ) : (
             <div className="subcategory-item">No Subcategories</div>
           )}
         </div>
       )}
                         </div>
                         
                         
                         
            ))}
          </div>

          <div className='iconss row px-1 mt-5'>
           <div className=' col-md-1 px-3'>
         <p> <Link to={`${settings?.facebookAddress}`}> <i className="fa-brands fa-facebook h4 cursor-pointer" style= {{color:"#ef4423"}}></i> </Link> </p>
          <p> <Link to={`${settings?.linkedinAddress}`}><i className="fa-brands fa-linkedin h4 cursor-pointer" style= {{color:"#ef4423"}}></i></Link>   
          </p>
<p>      <Link to={`${settings?.webSite}`}> <i className="fa-solid fa-globe h4 cursor-pointer" style= {{color:"#ef4423"}}></i></Link>
</p>
</div>
          </div>
          

    </div>
      </div>
     



       
      
  </>
}
