import React, { useContext , useState ,useEffect, useRef} from 'react'
import {Link, useNavigate} from 'react-router'
import { UserToken } from '../../Context/UserToken'
import {CartContext} from '../../Context/CartContext.js'
import brandlogo from '../../Assets/icon-removebg-preview_enhanced.png'
import axios from 'axios'
export default function Navbar() {
let navigate= useNavigate()
let {userToken , setUserToken} = useContext(UserToken)

let {numOfCartItems,setNumOfCartItems , getUserCart} = useContext(CartContext)
let [activeNavItem, setActiveNavItem] = useState('/'); // Default active item
let [categories , setCategories]=useState(null)
const [activeDropdown, setActiveDropdown] = useState(null);
let [settings , setSettings]=useState()
const [showMenu, setShowMenu] = useState(false);
const dropdownRef = useRef(null);
const [user , setUser] = useState()
  const toggleDropdown = () => setShowMenu((prev) => !prev);
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setShowMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);
   async function getSettings() {
     let {data} = await axios.get(`https://mcishop.vercel.app/api/v1/settings/`)
       setSettings(data?.setts[0])
    // console.log(data?.setts[0]);
    } 
  useEffect(() => {
    getSettings()
  }, [])
  const handleMouseEnter = (id) => {
    setActiveDropdown(id);
  };

  const handleMouseLeave = () => {
    setActiveDropdown(null);
  };
let handleNavClick = (path) => {
  setActiveNavItem(path);
};
async function getCart(){
  let {data} = await getUserCart()
  if(data?.status==='success'){
    setNumOfCartItems(data.cart.products.length)
    // console.log(data);
}else{
 // console.log(data);
}

}

async function getUserProfile() {
  try {
    const user_id = localStorage.getItem("user_id");
    if (!user_id) return;

    const { data } = await axios.get(`https://mcishop.vercel.app/api/v1/auth/${user_id}`);
     //  console.log(data);
    setUser(data?.user);
  } catch (error) {
    console.error("Error fetching user profile:", error);
  }
}
useEffect(() => {
  getUserProfile()
}, [])


async function getCategories() {
  let {data} = await axios.get(`https://mcishop.vercel.app/api/v1/categories`)
  // console.log(data);
   if(data)
   setCategories(data)
}
function logOut(){
  localStorage.removeItem('userToken');
  setUserToken(null);
  navigate('/login')
}


useEffect(() => {
  const token = localStorage.getItem("Token");
  if (token) {
    getCart();
  }
}, []); // On mount

useEffect(() => {
  if (userToken) {
    getCart();
  }
}, [userToken]); // On login

useEffect(() => {
  
getCategories()
}, [])

  return <>
  <nav className="navbar navbar-expand-lg bg-body-tertiary">
      <div className="container">
        <Link className="navbar-brand d-flex flex-column align-items-start" to="#">
          <img src={brandlogo} alt="Mci-Shop" className="brand-logo" style={{ height: "40px", width: "auto" }} />
        </Link>

        <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarSupportedContent">
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className="collapse navbar-collapse" id="navbarSupportedContent">
          <ul className="navbar-nav me-auto mb-2 mb-lg-0">
            <li className={`nav-item me-2 ${activeNavItem === "/" ? "active" : ""}`} onClick={() => handleNavClick("/")}>
              <Link className="nav-link" to="/">Home</Link>
            </li>
            <li className={`nav-item me-2 ${activeNavItem === "/products" ? "active" : ""}`} onClick={() => handleNavClick("/products")}>
              <Link className="nav-link" to="/products">Products</Link>
            </li>

            {/* Categories Dropdown */}
            <li className={`nav-item dropdown ${activeNavItem === "/categories" ? "active" : ""}`} onClick={() => handleNavClick("/categories")}>
              <Link className="nav-link dropdown-toggle" to="#" id="navbarDropdown" role="button" data-bs-toggle="dropdown" aria-expanded="false">
                Categories
              </Link>

              {/* Main Dropdown Menu */}
              <ul className="dropdown-menu">
                {categories?.categories.map((cat) => (
                  <li key={cat._id} className={`dropdown-submenu dropend position-relative`}
                      onMouseEnter={() => handleMouseEnter(cat._id)}
                      onMouseLeave={handleMouseLeave}>
                    
                    <Link className="dropdown-item dropdown-toggle" to={`/categories/${cat.slug}`}>{cat.name}</Link>

                    {/* Subcategories Dropdown */}
                    {cat.subcategories?.length > 0 && (
                      <ul className={`dropdown-menu position-absolute start-100 top-0 ${activeDropdown === cat._id ? "show" : ""}`}>
                        {cat.subcategories.map((sub) => (
                          <li key={sub._id}>
                            <Link className="dropdown-item" to={`/categories/${cat.slug}/subcategories/${sub.slug}`}>{sub.name}</Link>
                          </li>
                        ))}
                      </ul>
                    )}
                  </li>
                ))}
              </ul>
            </li>

            <li className={`nav-item me-2 ${activeNavItem === "/brands" ? "active" : ""}`} onClick={() => handleNavClick("/brands")}>
              <Link className="nav-link" to="/brands">Brands</Link>
            </li>
            <li className={`nav-item me-2 ${activeNavItem === "/services" ? "active" : ""}`} onClick={() => handleNavClick("/services")}>
              <Link className="nav-link" to="/services">Services</Link>
            </li>
          </ul>
          <ul className="navbar-nav ms-auto mb-2 mb-lg-0">
      <li className="nav-item d-flex align-items-center">  
         <Link className="nav-link text-main" to={'/cart'}> <i className="fas fa-shopping-cart cartIcon"><span className="cartNums">{numOfCartItems}</span></i> </Link>
     <Link to={`${settings?.facebookAddress}`}> <i className="fab fa-facebook mx-1 cursor-pointer text-main"></i></Link>
      <Link to={`${settings?.linkedinAddress}`}><i className="fab fa-linkedin mx-1 cursor-pointer text-main"></i></Link>
     <Link to={`${settings?.webSite}`}> <i class="fa-solid fa-globe mx-1 cursor-pointer text-main"></i></Link>
        {userToken?<>
          <div className="position-relative">
          <i class="fa-solid fa-circle-user mx-1 cursor-pointer text-main"  onClick={toggleDropdown}>
           
           </i>

      {showMenu && (
        <div className="dropdown-menu show  mt-2 shadow rounded" ref={dropdownRef} style={{
          display: 'block',
          minWidth: '220px',
          position: 'absolute',
          top: '100%',
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 999,
        }}>
          <div className="px-5 py-3 border-bottom text-center">
          <i class="fa-solid fa-circle-user mx-1 mb-3 fa-xl"  ></i>

            <strong>{user?.email || 'Email'}</strong>
          </div>
          <button className="dropdown-item">
            <Link className='text-black' to={`/personal/${user?._id}`}> Personal Information</Link>
          </button>
          <button className="dropdown-item">
          <Link className='text-black' to={`/orders/${user?._id}`}> Orders </Link>
          </button>
          <button className="dropdown-item text-danger" onClick={logOut}>
           Sign Out
          </button>
        </div>
      )}
    </div>



         



         
         
        </>:<></>
        }
       
        </li>
        {userToken?<>
        <li className="nav-item">
        <span onClick={()=>logOut()} className="nav-link fw-bold cursor-pointer">Sign out</span>
      </li>
      </>
        : <><li>
        <Link className="nav-link" to={'login'}>Login</Link>
          </li>
          <li className="nav-item">
          <Link className="nav-link" to={'register'}>Sign up</Link>
        </li> </>}
        </ul>
        </div>
      </div>
    </nav>
  </>
}
