import React, { useContext, useState } from "react";
import {useFormik} from 'formik';
import * as Yup from 'yup';
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { UserToken } from "../../Context/UserToken";
import { Link } from "react-router-dom";
import { Helmet } from "react-helmet";
import { FaEye, FaEyeSlash } from 'react-icons/fa'; 

export default function Signin() {
    let{setUserToken} = useContext(UserToken)
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState(null);
      const [showPassword, setShowPassword] = useState(false);
    
    let navigate=useNavigate();
    
    async function login(values){
      setLoading(true)
          let {data} = await axios.post('https://mcishop.vercel.app/api/v1/auth/signin', values,{
            Content_Type:"application/json"
          })
          .catch((err)=>{
            setError(err.response.data.message);
           console.log(err.response.data.message);
           
            setLoading(false)
        
          })
  
           if(data.message==="signed in successfully"){
           // console.log(data?.user._id);
            
            setLoading(false)
            localStorage.setItem( 'userToken' , data?.token)
            localStorage.setItem( 'user_id' , data?.user._id)
            setUserToken(data.token)
                navigate('/')
                
  
           }
           
    }
     let validationSchema = Yup.object({
    email:Yup.string().email('invalid email!').required('Email is required!'),
     password:Yup.string().matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/,'invalid password!').required('Password is required!'),
          
    }) 
   
    let formik= useFormik({
      initialValues:{
        email:'',
        password:''
      },validationSchema,
      onSubmit:login
    })
    return <>
    <Helmet>
      <title>Login</title>
    </Helmet>
                <div className="w-50 mx-auto py-4 " >
                        <div className="d-flex justify-content-center align-items-center my-3">
                                <h4>Login </h4>
                                </div>
          {error?<div className="alert alert-danger py-2">{error}</div>:"" }                                                 
          <form onSubmit={formik.handleSubmit}>
  
    <input placeholder="Enter your email" type="email" email="email" id="email" value={formik.values.email}  className="mb-3 form-control" onChange={formik.handleChange} onBlur={formik.handleBlur}/>
    {formik.errors.email && formik.touched.email? <div className="alert alert-danger py-2">{formik.errors.email}</div>:"" }                           
  
<div className="position-relative">
  <input
    type={showPassword ? "text" : "password"}
    name="password"
    id="password"
    value={formik.values.password}
    className="mb-2 form-control pe-5"
    onChange={formik.handleChange}
    onBlur={formik.handleBlur}
    placeholder="Enter your password"
  />
  <span
    onClick={() => setShowPassword(!showPassword)}
    style={{
      position: 'absolute',
      top: '50%',
      right: '12px',
      transform: 'translateY(-50%)',
      cursor: 'pointer',
      color: '#666',
    }}
  >
    {showPassword ? <FaEyeSlash /> : <FaEye />}
  </span>
</div>
{formik.errors.password && formik.touched.password ? (
  <div className="alert alert-danger py-2">{formik.errors.password}</div>
) : null}

  
                             
                              
  {loading==true?<button type="button" className="btn bg-main text-white">
                  <i className="fas fa-spinner fa-spin"></i>
                  </button> : <button disabled={(!(formik.isValid&&formik.dirty))} type="submit" className="btn bg-main text-white">Submit</button>}        
                                </form>
                    <div className="d-flex justify-content-center align-items-center mt-3">
                      {/* <Link to={`/forgetPassword`} className="text-danger">Forget Password?</Link>   */}
                      </div>
                      <div className="text-center mt-2">
                      <p><Link className=" text-decoration-none text-black" to={'/forgetPass'}><strong>Forget password? </strong></Link></p>

                        <p>Don't you have an account? <Link className=" text-decoration-none text-black" to={'/register'}><strong>Create an account</strong></Link></p>
                        </div>          
                       </div>
    </>
}
