import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link, useParams } from 'react-router-dom';
import { FaBox, FaMoneyBillAlt, FaClock } from 'react-icons/fa';
import Loadingscreen from '../Loadingscreen/Loadingscreen';

export default function Orders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
        const {user_id} = useParams()
        let userToken =localStorage.getItem('userToken')
 //let userId = localStorage.getItem('userId')
 let headers = {
    token : "Bearer "+userToken
 }
  useEffect(() => {
    async function fetchOrders() {
      try {
        setLoading(true);
        const { data } = await axios.get(`https://mcishop.vercel.app/api/v1/orders/${user_id}` ,{
            headers
        }
          
          
        );
        setOrders(data?.orders || []);
        console.log(data?.orders);
      } catch (err) {
        setError('Failed to load orders');
        console.error(err);
      } finally {
        setLoading(false);
      }
    }

    if (user_id) fetchOrders();
  }, [user_id]);
  
  return (
    <div className="container py-4">
      <h4 className="mb-4 text-center">🛒 Orders History</h4>
  
      {loading && <Loadingscreen />}
      {error && <div className="alert alert-danger">{error}</div>}
      {!loading && orders.filter(order => order.status === 'PAID').length === 0 && (
        <p className="text-center h3 ">No orders found.</p>
      )}
  
      {orders
        .filter(order => order.status === 'PAID')
        .map((order, index) => (
          <div className="card mb-4 shadow-sm w-75 mx-auto" key={order._id}>
            <div className="card-header d-flex justify-content-between align-items-center">
              <span><strong>Order - {index + 1}</strong></span>
              <span><small>{new Date(order.createdAt).toLocaleDateString()}</small></span>
            </div>
            <div className="card-body">
              <ul className="list-group list-group-flush">
                {order.products.map((prod, idx) => (
                  <li className="list-group-item" key={idx}>
          <Link to={`/productDetails/${prod.product_id?.slug}`} className=' text-black'><strong>{prod.product_id?.title || 'Product not found'}</strong></Link>
                    <span className="ms-2 text-muted">({prod.quantity} pcs)</span>
                    <span className="float-end">
                      {prod.product_id?.price
                        ? `EGP ${prod.product_id.price * prod.quantity}`
                        : ''}
                    </span>
                  </li>
                ))}
              </ul>
              <div className="mt-3 text-end">
                <strong>Total: EGP {order.total_price}</strong>
              </div>
            </div>
          </div>
        ))}
    </div>
  );
  
}
