import React, { useState } from "react";
import {useFormik} from 'formik';
import * as Yup from 'yup';
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { Helmet } from "react-helmet";
import { FaEye, FaEyeSlash } from 'react-icons/fa'; 

export default function Signup() {
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState(null)
      const [showPassword, setShowPassword] = useState(false);
    
    let navigate=useNavigate();

    async function register(values){
      setLoading(true)
          let {data} = await axios.post('https://mcishop.vercel.app/api/v1/auth/signup', values , {
            Content_Type:"application/json"
          }).catch((err)=>{
            if (err.response && err.response.data && err.response.data.message) {
              setError(err.response.data.message); // <-- This will show the backend message
            } else {
              setError('Something went wrong. Please try again.');
            }
            setLoading(false)
          
          })
  
           if(data.message === "Signed up successfully"){
            setLoading(false)
            navigate('/login')
          
           }
           
    }
  
    let validationSchema = Yup.object({
      companyName: Yup.string()
        .min(3, 'The Minimum length is 3!')
        .max(15, 'The Maximum length is 15!')
        .required('Company Name is required!'),
    
      email: Yup.string()
        .email('Invalid email!')
        .required('Email is required!'),
    
      phone: Yup.string()
        .matches(/^01[0125][0-9]{8}$/, 'Phone number must be a valid Egyptian number (e.g. 010xxxxxxxx)')
        .required('Phone number is required!'),
    
      password: Yup.string()
        .matches(
          /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/,
          'Password must include uppercase, lowercase, number, special character and be at least 8 characters!'
        )
        .required('Password is required!'),
    });
    
    let formik= useFormik({
      initialValues:{
        companyName:'',
        email:'',
        password:'',
        phone:''
        
      },validationSchema, onSubmit:register
    })
    return <>
        <Helmet>
          <title>Register</title>
        </Helmet>
  
                       <div className="w-50 mx-auto py-4 ">
                                <h4 className=" mb-3 text-center">Sign up</h4>
          {error?<div className="alert alert-danger py-2">{error}</div>:"" }                                                 
          <form onSubmit={formik.handleSubmit}>
             
    <input  placeholder="Enter company Name" type="text" name="companyName" id="companyName" value={formik.values.companyName}  className="mb-3 form-control" onChange={formik.handleChange} onBlur={formik.handleBlur}/>
   {formik.errors.companyName && formik.touched.companyName? <div className="alert alert-danger py-2">{formik.errors.companyName}</div>:"" }                           
  
    <input placeholder="Enter your Email" type="email" name="email" id="email" value={formik.values.email}  className="mb-3 form-control" onChange={formik.handleChange} onBlur={formik.handleBlur}/>
<input
  type="tel"
  name="phone"
  id="phone"
  value={formik.values.phone}
  className="form-control mb-3"
  onChange={formik.handleChange}
  onBlur={formik.handleBlur}
  placeholder="Enter your phone"
/>
{formik.errors.phone && formik.touched.phone ? (
  <div className="alert alert-danger py-2">{formik.errors.phone}</div>
) : null}

  
    {formik.errors.email && formik.touched.email? <div className="alert alert-danger py-2">{formik.errors.email}</div>:"" }                           
<div className="position-relative mb-3">
  <input
    type={showPassword ? "text" : "password"}
    name="password"
    id="password"
    value={formik.values.password}
    className=" form-control pe-5"
    onChange={formik.handleChange}
    onBlur={formik.handleBlur}
    placeholder="Enter password"
  />
  <span
    onClick={() => setShowPassword(!showPassword)}
    style={{
      position: 'absolute',
      top: '50%',
      right: '10px',
      transform: 'translateY(-50%)',
      cursor: 'pointer',
      color: '#666'
    }}
  >
    {showPassword ? <FaEyeSlash /> : <FaEye />}
  </span>
</div>
{formik.errors.password && formik.touched.password && (
  <div className="alert alert-danger py-2">{formik.errors.password}</div>
)}

                             
  {loading==true?<button type="button" className="btn bg-main text-white">
                  <i className="fas fa-spinner fa-spin"></i>
                  </button> : <button disabled={!(formik.isValid&&formik.dirty)} type="submit" className="btn bg-main text-white">Submit</button>}
                          
  
                                </form>
                       </div>
    </>
}
