import React, { useEffect, useState } from 'react'
import Loadingscreen from '../Loadingscreen/Loadingscreen';
import { Helmet } from 'react-helmet';
import axios from 'axios';

export default function CheckoutDetails() {
  const [settings, setSettings] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const { data } = await axios.get("http://mcishop.vercel.app/api/v1/settings/");
         
         setSettings(data?.setts?.[0] );
    
      } catch (error) {
        console.error("Failed to fetch settings:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchSettings();
  }, []);

  return <>

<Helmet>
    <title>Checkout</title>
  </Helmet>
   {loading?<>
   <Loadingscreen/>
   </>:<>
   <div className="d-flex justify-content-center align-items-center min-vh-100 ">
      <div className="card shadow-sm p-4 text-center" style={{ maxWidth: "400px" }}>
        <div className="card-body">
          <h2 className="text-success fw-bold">Thank You for Your Order!</h2>
          <p className="text-muted mt-3">
            Your order has been received successfully. A team member will contact you soon to confirm the details.
          </p>
          <hr />
          <h5 className="fw-semibold"> Contact Information:</h5>
          <p className="text-muted">
          <i class="fa-solid fa-envelope"></i> Email: <a href={`mailto:${settings?.email}`} className="text-dark">{settings?.email}</a>
          </p>
          <p className="text-muted"><i className="fa-solid fa-phone"></i> Phone: <a href={`tel:${settings?.phone}`} className=" text-dark">{settings?.phone}</a></p>
          <p className="text-muted"><i class="fa-solid fa-globe"> </i> Website: <a href={`${settings?.webSite}`} className="text-dark">{settings?.webSite}</a></p>
          <button 
            onClick={() => window.location.href = "/"} 
            className="btn btn-success mt-3 w-100"
          >
            Return to Home
          </button>
        </div>
      </div>
    </div>
   </>}





    
   
  </>
}
