import React, { useState } from 'react';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet';
import { FaEye, FaEyeSlash } from 'react-icons/fa'; 
export default function ResetPassword() {
  const { token } = useParams();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const validationSchema = Yup.object({
    newPassword: Yup.string()
      .matches(
        /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/,
        'Password must be at least 8 characters and include uppercase, lowercase, number, and special character.'
      )
      .required('New password is required'),
  });

  const formik = useFormik({
    initialValues: {
      newPassword: '',
    },
    validationSchema,
    onSubmit: async (values) => {
      setLoading(true);
      setError('');
      setMessage('');

      try {
        const { data } = await axios.post(
          `https://mcishop.vercel.app/api/v1/auth/resetPassword/${token}`,
          values,
          {
            headers: {
              'Content-Type': 'application/json',
            },
          }
        );

        setLoading(false);
        setMessage(data.message);
        setTimeout(() => {
          navigate('/login'); // Redirect to login after successful reset
        }, 2000);
      } catch (err) {
        setLoading(false);
        const errorMsg = err.response?.data?.message || 'Something went wrong';
        setError(errorMsg);
      }
    },
  });

  return (
    <>
      <Helmet>
        <title>Reset Password</title>
      </Helmet>

      <div className="w-50 mx-auto py-4" style={{ fontFamily: 'sans-serif' }}>
        <h2 className="text-center my-4">Reset Your Password</h2>

        {message && <div className="alert alert-success">{message}</div>}
        {error && <div className="alert alert-danger">{error}</div>}

        <form onSubmit={formik.handleSubmit}>
        <label htmlFor="newPassword" className="mb-1">New Password</label>
<div className="position-relative">
  <input
    type={showPassword ? "text" : "password"}
    id="newPassword"
    name="newPassword"
    className="form-control mb-2 pe-5"
    value={formik.values.newPassword}
    onChange={formik.handleChange}
    onBlur={formik.handleBlur}
    placeholder="Enter your new password"
  />
  <span
    onClick={() => setShowPassword(!showPassword)}
    style={{
      position: 'absolute',
      right: '10px',
      top: '50%',
      transform: 'translateY(-50%)',
      cursor: 'pointer',
      color: '#666'
    }}
  >
    {showPassword ? <FaEyeSlash /> : <FaEye />}
  </span>
</div>

          {formik.errors.newPassword && formik.touched.newPassword && (
            <div className="alert alert-danger py-2">
              {formik.errors.newPassword}
            </div>
          )}

          <button
            type="submit"
            className="btn bg-main text-white mt-2"
            disabled={!formik.isValid || !formik.dirty || loading}
          >
            {loading ? (
              <i className="fas fa-spinner fa-spin"></i>
            ) : (
              'Reset Password'
            )}
          </button>
        </form>
      </div>
    </>
  );
}

