import axios from 'axios'
import React, { useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import Loadingscreen from '../Loadingscreen/Loadingscreen'
import { Helmet } from 'react-helmet'
export default function Personal() {
    let userToken = localStorage.getItem('userToken')
    const [user , setUser]=useState()
      let [loading , setLoading] = useState(true)
    
    async function getUserProfile() {
      try {
        const user_id = localStorage.getItem("user_id");
        if (!user_id) return;
    
        const { data } = await axios.get(`https://mcishop.vercel.app/api/v1/auth/${user_id}`);
           //console.log(data);
        setUser(data?.user);
        setLoading(false)
      } catch (error) {
        console.error("Error fetching user profile:", error);
      }
    }
    useEffect(() => {
      getUserProfile()
    }, [])
   

  return<>
    <Helmet>
         <title>Personal information</title>
       </Helmet>
       {loading?<>
           <Loadingscreen/>
       </> :
       <>
        <div className="container my-5">
    <div className="w-50 mx-auto card border-0 shadow rounded-3">
      <div className="card-header bg-light border-bottom d-flex align-items-center">
        <i className="bi bi-person-circle fs-3 me-2 text-primary"></i>
        <h5 className="mb-0">Personal Information</h5>
      </div>
      <div className="card-body">
        <div className="row mb-3">
          <div className="col-md-4 fw-semibold text-muted">Company Name</div>
          <div className="col-md-8">{user?.companyName || 'Not Provided'}</div>
        </div>
        <hr />
        <div className="row mb-3">
          <div className="col-md-4 fw-semibold text-muted">Email Address</div>
          <div className="col-md-8">{user?.email || 'Not Provided'}</div>
        </div>
        <hr />
        <div className="row mb-3">
          <div className="col-md-4 fw-semibold text-muted">Phone Number</div>
          <div className="col-md-8">{user?.phone || 'Not Provided'}</div>
        </div>
        <hr />
      </div>
    </div>
    <div className="text-center mt-5">
              <p className="text-muted mb-2">Do you want to change your password?</p>
              <Link to={`/forgetPass/`} className="text-black">
                Change Password
              </Link>
            </div>
  </div>
       </>
       }




   
  </>

}
