import axios from 'axios'
import React, { useContext, useEffect, useState } from 'react'
import { Helmet } from 'react-helmet'
import { Link, useNavigate, useParams } from 'react-router-dom'
import Loadingscreen from '../Loadingscreen/Loadingscreen'
import { Box, Pagination } from '@mui/material'
import toast from 'react-hot-toast'
import { CartContext } from '../../Context/CartContext'
import SearchBar from '../SearchBar/Searchbar'

export default function Categorydetails() {
  let[products , setProducts] = useState(null)
  let[loading , setLoading] = useState(true)
    let {addToCart , setNumOfCartItems} = useContext(CartContext)
  
  let navigate= useNavigate()
  let itemsPerPage = 10;
  const [currentPage, setCurrentPage] = useState(1);
  const handlePageChange = (event, value) => {
    setCurrentPage(value);
  };
  let {categorySlug } = useParams()
  async function getProducts(keyword){
    const {data} = await axios.get(`https://mcishop.vercel.app/api/v1/categories/${categorySlug}/products` , {
      params: { keyword },
    })
        setProducts(data)
        setLoading(false)
        console.log(data);
        
   }

 
  const offset = (currentPage - 1) * itemsPerPage;
  const currentItems = products?.category.products?.slice(offset, offset + itemsPerPage);
  async function handlePost(productId) {
    if(localStorage.getItem('userToken')){
     let {data} = await  addToCart(productId)
   
        
 if (data?.status=="Added successfully"){
toast.success('added successfully to your cart' , {
 duration: 3000,
})

setNumOfCartItems(data?.cart.products?.length )
}
   
   }else{
     navigate('/login')
   }
 
}
  useEffect(() => {
    getProducts()
  }, [categorySlug])
  
  
  return <>
        <Helmet>
         <title>{products?.category.name}</title>
       </Helmet>
       {loading?<>
           <Loadingscreen/>
       </> :
       <>
        <div className="container mb-4"> 

                
       <div className="row gap-5 g-3 mt-5  mx-auto">
        { currentItems?.map((pro)=>(
             <div key={pro._id} className="col-md-2 mb-2 mx-auto position-relative">
             <div className="product p-2 position-relative">
        < Link className='text-decoration-none text-black' to={`/productDetails/${pro.slug}`}>
      <div className='prodCont py-3'><img loading='lazy' src={pro.cover_image?.path} className="w-100"  alt={pro.description} />
      </div>
        <h5  className="text-center h5 mt-2 mb-2">{pro.title}</h5>
        <h6 className=' fw-bolder text-center '>{pro.subcategory_id?.name}</h6>

        <div className="text-center text-main">
          <h6 className=' fw-bolder '>{pro.brand_id?.name}</h6>
         <h6 className='text-center fw-bold '><span className='pe-1'>{pro.price}</span> EGP</h6>
        </div>
      </Link>
      <div className="d-flex align-items-center justify-content-center heart ">
         <button onClick={()=>{handlePost(pro.id)}}  className="btn bg-main w-75  text-white mt-1">Add TO Cart</button>
         </div>
        
         </div>
             </div>
        )) }
       </div>
       <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
      }}
      
    >
    
      <Pagination
        count={Math.ceil(products?.category.products?.length / itemsPerPage)}
        page={currentPage}
        onChange={handlePageChange}
        className='mt-4'
      />
      
      <Box sx={{ mt: 2, fontSize: '1rem', fontWeight: 'bold' }}>
        Page {currentPage} of {Math.ceil(products?.category.products?.length / itemsPerPage)}
      </Box>
    </Box>
       </div>
       </>}
       
       
  </>
}
