import React, { useEffect, useState } from 'react'
import icon from '../../Assets/WhatsApp.svg.webp'
import { Link } from 'react-router-dom'
import axios from 'axios'
export default function WhatsappIcon() {
  let [settings , setSettings]=useState()
   async function getSettings() {
     let {data} = await axios.get(`http://localhost:3000/api/v1/settings/`)
       setSettings(data?.setts[0])
    // console.log(data?.setts[0]);
    } 
  useEffect(() => {
    getSettings()
  }, [])
  return <>
    <div className='whatsLayer'>
    <Link
    to={`https://wa.me/${settings?.phone}`}
    target="_blank"
    rel="noopener noreferrer"
    className="whatsapp-link"
  >
    <img src={icon} alt="WhatsApp" className="w-100" />
  </Link>
      <div className='disc d-none'>
     <p>WhatsAPP us</p>
      </div>
    </div>
    
    
  </>
}
