import axios from 'axios'
import React, { useContext, useEffect, useState } from 'react'
import { Link, useParams , useNavigate } from 'react-router-dom'
import toast  from 'react-hot-toast';
import { CartContext } from '../../Context/CartContext'
import { Helmet } from 'react-helmet'
import Loadingscreen from '../Loadingscreen/Loadingscreen'
import img2 from '../../Assets/icon-removebg-preview_enhanced.png'
import Slider from 'react-slick';
export default function ProductDetails() {
      let navigate= useNavigate()
    let [product , setProduct] = useState(null)
    let [loading , setLoading] = useState(true)
    let {addToCart ,setNumOfCartItems} = useContext(CartContext)
    let {slug}=useParams()
   async  function getProductDetails(){
      const {data} = await axios.get(`https://mcishop.vercel.app/api/v1/products/${slug}`)
       
       setProduct(data)
       setLoading(false)
    }
    async function postCart(productId){
      if(localStorage.getItem('userToken')){
        let {data} = await  addToCart(productId)
    if (data?.status=="Added successfully"){
 toast.success('added successfully to your cart' , {
    duration: 3000,
 })

 setNumOfCartItems(data?.cart.products.length )
}
    
      }else{
        navigate('/login')
      }
    
   }
   var settings = {
    dots: false,
    infinite: true,
    autoplaySpeed:1000,
     autoplay:true,
     arrows:false,
    slidesToShow: 1,
    slidesToScroll: 1
  }
    
     useEffect(()=>{
         getProductDetails()
     },[]) 
  return <>
        <Helmet>
          <title>{`${product?.product.title}`} </title>
          <link rel="icon" href="" />
        </Helmet>
    {loading?<>
    <Loadingscreen/>
    </>:<>
      <div className="container">
    <div className="row p-5 w-75 mx-auto my-5 d-flex justify-content-between ">
   <div className="col-md-3 py-5">
    {product?.product.images.length>1 ?<Slider {...settings}>
      {product?.product.images.map((image)=> <img key={product?.product.id} loading='lazy' src={image.image_id.path} alt={product?.product.title} className='w-100' />)}
    </Slider> : <>     <img loading='lazy' src={product?.product.cover_image.path} alt={product?.product.description} className='w-100' />
    </>}
   {/* <Slider {...settings}>
      {data?.data.data.images.map((image)=> <img key={data?.data.data.id} src={image} alt={data?.data.data.title} />)}
    </Slider>
     <img loading='lazy' src={product?.product.cover_image.path} alt={product?.product.description} className='w-100' /> */}
      </div>
     <div className=" col-md-7 py-4">
           <div className=' text-center '>
            <h2 className="h4 fw-bold">{product?.product.title}</h2>
            <p className="text-muted">{product?.product.description}</p>
            <h5 className=" fw-bold">{product?.product.category_id?.name}</h5>
            <h3 className="h4 fw-bold text-main">{product?.product.brand_id?.name}</h3>
            <h6 className='text-center'>{product?.product.price} EGP</h6>
          
         <button onClick={()=>{postCart(product.product.id)}} className="btn  btn-outline-dark  mt-3">Add TO Cart</button>
           </div>
     </div>
          </div>


          {product?.product.features?<>
                  <div className="row py-5">
                    <div className='separator'>
                      <div className='desc p-2 text-center '>
                         <p className='h6 w fw-bold'>Description</p>
                      </div>
                      
                    </div>
                    <div className='features py-4 w-75 h6'>
                    <p>{product?.product.features}.</p>
                      <div>

                      </div>
                    </div>
                  </div>
          </>:<></>}
    </div>
    </>}
  </>
}
